#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq, PartialOrd, Ord)]
#[serde(rename_all = "UPPERCASE")]
pub enum RiskTier {
    R0,
    R1,
    R2,
    R3,
    R4,
}

impl RiskTier {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::R0 => "R0",
            Self::R1 => "R1",
            Self::R2 => "R2",
            Self::R3 => "R3",
            Self::R4 => "R4",
        }
    }
}

impl FromStr for RiskTier {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.trim().to_ascii_uppercase().as_str() {
            "R0" => Ok(Self::R0),
            "R1" => Ok(Self::R1),
            "R2" => Ok(Self::R2),
            "R3" => Ok(Self::R3),
            "R4" => Ok(Self::R4),
            other => Err(format!("unknown risk tier: {other}")),
        }
    }
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "kebab-case")]
pub enum SandboxProfile {
    TrustedDev,
    DevelopmentConfined,
    EnterpriseRestricted,
    EnterpriseConnected,
    ReadOnlyModel,
}

impl SandboxProfile {
    pub fn parse(value: &str) -> Option<Self> {
        match value.trim().to_ascii_lowercase().as_str() {
            "trusted-dev" => Some(Self::TrustedDev),
            "development-confined" => Some(Self::DevelopmentConfined),
            "enterprise-restricted" => Some(Self::EnterpriseRestricted),
            "enterprise-connected" => Some(Self::EnterpriseConnected),
            "read-only-model" => Some(Self::ReadOnlyModel),
            _ => None,
        }
    }

    pub fn as_str(self) -> &'static str {
        match self {
            Self::TrustedDev => "trusted-dev",
            Self::DevelopmentConfined => "development-confined",
            Self::EnterpriseRestricted => "enterprise-restricted",
            Self::EnterpriseConnected => "enterprise-connected",
            Self::ReadOnlyModel => "read-only-model",
        }
    }

    pub fn requires_isolation(self) -> bool {
        !matches!(self, Self::TrustedDev | Self::ReadOnlyModel)
    }
}

impl FromStr for SandboxProfile {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Self::parse(s).ok_or_else(|| format!("unknown sandbox profile: {s}"))
    }
}

