#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct WorkContract {
    pub api_version: String,
    pub kind: String,
    pub metadata: ContractMetadata,
    pub spec: ContractSpec,
}

impl WorkContract {
    pub fn load(path: &std::path::Path) -> Result<Self, String> {
        let text = std::fs::read_to_string(path)
            .map_err(|e| format!("cannot read work contract {}: {e}", path.display()))?;
        let contract: Self =
            serde_json::from_str(&text).map_err(|e| format!("invalid work contract JSON: {e}"))?;
        if contract.api_version != "jani.dev/v1alpha1" {
            return Err("unsupported contract apiVersion; expected jani.dev/v1alpha1".into());
        }
        if contract.kind != "WorkContract" {
            return Err("contract kind must be WorkContract".into());
        }
        if contract.metadata.task_id.trim().is_empty()
            || contract.metadata.tenant.trim().is_empty()
            || contract.metadata.principal.trim().is_empty()
        {
            return Err("contract requires taskId, tenant and principal".into());
        }
        Ok(contract)
    }
}

