#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PluginManifest {
    pub api_version: String,
    pub kind: String,
    pub metadata: PluginMetadata,
    pub spec: PluginSpec,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub integrity: Option<PluginIntegrity>,
}

impl PluginManifest {
    /// Digest covers the manifest with integrity removed, so signatures can be
    /// detached and re-verified after distribution.
    pub fn computed_digest(&self) -> String {
        let mut clone = self.clone();
        clone.integrity = None;
        sha256_hex(&serde_json::to_vec(&clone).unwrap_or_default())
    }

    pub fn load(path: &std::path::Path) -> Result<Self, String> {
        let text = std::fs::read_to_string(path)
            .map_err(|e| format!("cannot read plugin manifest {}: {e}", path.display()))?;
        let manifest: Self = serde_json::from_str(&text)
            .map_err(|e| format!("invalid plugin manifest {}: {e}", path.display()))?;
        if manifest.kind != "Plugin" {
            return Err("plugin manifest kind must be Plugin".into());
        }
        if manifest.metadata.id.trim().is_empty() || manifest.metadata.version.trim().is_empty() {
            return Err("plugin manifest requires metadata.id and metadata.version".into());
        }
        Ok(manifest)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn classifications_are_ordered() {
        assert!(Classification::Secret > Classification::Restricted);
        assert_eq!(
            Classification::Confidential.max(Classification::Public),
            Classification::Confidential
        );
    }

    #[test]
    fn resource_canonicalization_rejects_traversal() {
        assert_eq!(
            canonical_resource("repo", "./src\\main.rs").unwrap(),
            "repo:src/main.rs"
        );
        assert!(canonical_resource("repo", "../secret").is_err());
    }

    #[test]
    fn ids_are_unique_per_call() {
        let a = new_id("inv");
        let b = new_id("inv");
        assert_ne!(a, b);
        assert!(a.starts_with("inv-"));
    }

    #[test]
    fn work_contract_version_is_enforced() {
        let contract = WorkContract {
            api_version: "jani.dev/v2".into(),
            kind: "WorkContract".into(),
            metadata: ContractMetadata {
                task_id: "task-1".into(),
                tenant: "tenant-a".into(),
                principal: "human-1".into(),
                workspace: ".".into(),
            },
            spec: ContractSpec {
                purpose: "SOFTWARE_DEV".into(),
                capabilities: vec![],
                write_paths: vec![],
                sandbox_profile: None,
                data_classification: None,
                budget: ContractBudget::default(),
                acceptance: vec![],
            },
        };
        let temp = std::env::temp_dir().join(format!(
            "jani-contract-version-{}.json",
            crate::process::unique_id()
        ));
        std::fs::write(&temp, serde_json::to_vec(&contract).unwrap()).unwrap();
        let err = WorkContract::load(&temp).unwrap_err();
        assert!(err.contains("apiVersion"));
        let _ = std::fs::remove_file(temp);
    }

    #[test]
    fn plugin_digest_ignores_integrity() {
        let mut manifest = PluginManifest {
            api_version: "plugins.jani.dev/v1alpha1".into(),
            kind: "Plugin".into(),
            metadata: PluginMetadata {
                id: "com.example.demo".into(),
                name: "Demo".into(),
                version: "1.0.0".into(),
                publisher: "example".into(),
            },
            spec: PluginSpec {
                kind: PluginKind::Tool,
                runtime: PluginRuntime {
                    runtime_type: "builtin".into(),
                    artifact: String::new(),
                    entrypoint: "example.uppercase".into(),
                },
                capabilities: vec![],
                requested_permissions: None,
            },
            integrity: None,
        };
        let d1 = manifest.computed_digest();
        manifest.integrity = Some(PluginIntegrity {
            digest: d1.clone(),
            signature: "00".into(),
            key_id: "default".into(),
        });
        assert_eq!(d1, manifest.computed_digest());
    }
}
